-- Adding guarded columns enforces checks without rebuilding populated tables.
ALTER TABLE mat_activity_events ADD COLUMN validation_guard INTEGER CHECK ((json_type("properties") = 'object' AND length(cast("properties" as blob)) <= 256) AND (length(cast("path" as blob)) <= 64) AND ("name" IN ('page_view','scroll_depth','active_time','link_click','reaction_attempt','reaction_success','reaction_failure','reservation_submit_click','reservation_reason_opened','reservation_attempt','reservation_success','reservation_failure','photo_selected','camera_start_attempt','camera_ready','camera_failure','camera_switch','camera_stop','camera_retake','photo_capture_attempt','photo_capture_success','photo_capture_failure','photo_capture_cancelled','photo_share_attempt','photo_share_success','photo_share_failure','photo_share_cancelled','photo_share_unavailable','photo_download_click')));
--> statement-breakpoint
ALTER TABLE mat_reservations ADD COLUMN validation_guard INTEGER CHECK (("reason" IN ('story','rest','project','donate','other')) AND ("payment_method" IN ('deposit','easy','transfer','other')) AND ("amount" > 0 AND "amount" <= 2147483647) AND (length(trim("display_name")) BETWEEN 1 AND 40) AND (length(trim("title")) BETWEEN 1 AND 80) AND (length("reason_other") <= 300) AND ("email" IS NULL OR length("email") BETWEEN 1 AND 254) AND ("phone" IS NULL OR (length("phone") IN (10,11) AND substr("phone",1,2)='01' AND substr("phone",3,1) IN ('0','1','6','7','8','9') AND "phone" NOT GLOB '*[^0-9]*')) AND (length("photo") > 0) AND (length(cast(trim("story") as blob)) BETWEEN 1 AND 1000) AND ("reason" <> 'other' OR length(trim("reason_other")) > 0));
--> statement-breakpoint
ALTER TABLE mat_stories ADD COLUMN validation_guard INTEGER CHECK (("mat_number" BETWEEN 1 AND 10000) AND ("mat_size" IN ('small','large')) AND (length(trim("display_name")) BETWEEN 1 AND 40) AND (length("title") <= 80) AND (length("photo") > 0) AND ("payment_verified" IN (0,1) AND "published" IN (0,1)) AND (length(cast(trim("story") as blob)) BETWEEN 1 AND 1000) AND ("published" = 0 OR "payment_verified" = 1));
